if(/\b(?:INSERT|UPDATE|DELETE|ALTER|CREATE|DROP|GRANT|REVOKE|TRUNCATE|CALL)\b/i.test(lifecycle+mfa))throw new Error('Only declared metadata SELECT capture');
const split=mfa.indexOf('\nSELECT n.nspname');if(split<0)throw new Error('MFA metadata split missing');const queries=[['lifecycle',lifecycle],['legacy_mfa_helpers',mfa.slice(0,split)],['mfa_factor_session_columns',mfa.slice(split)]];const results=[];
for(const [environment,ref,ledger]of [['PROD','YOUR_PROJECT_REF',457],['DEV','YOUR_PROJECT_REF',432]]){const captured=[];for(const [kind,sql]of queries){const r=await fetch('https://api.supabase.com/v1/projects/'+ref+'/database/query',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({query:sql,read_only:true}),signal:AbortSignal.timeout(30000)});const data=await r.json();if(!r.ok)throw new Error('Recovery metadata '+kind+' HTTP'+r.status);captured.push({kind,sourceSha256:sha(sql),rows:data});}const c=captured[0].rows[0]?.recovery_catalog;if(c?.engine!=='170006'||Number(c.ledger_count)!==ledger||c.latest!=='20261005043000'||c.namespace_absent!==true)throw new Error('Exact recovery target or namespace drift');const file=root+'/FVI-RECOVERY-MFA-CATALOG-'+environment+'-457-432-'+Date.now()+'.json';await writeFile(file,JSON.stringify({at:new Date().toISOString(),environment,ref,ledger,captured,readOnly:true,noBusinessAuthRowsRead:true},null,2),{flag:'wx'});results.push({environment,ref,engine:c.engine,ledger,latest:c.latest,namespaceAbsent:c.namespace_absent,fingerprint:c.fingerprint,receipt:file});}
